insert into public.diretorio_salas (nome,num,nome_en,nome_pt,descricao_en,descricao_pt,raridade_en,raridade_pt,custo_en,custo_pt,tipo_en,tipo_pt,categorias,diretorio,imagem,fonte,atualizado_em) values
('The Foundation',1,'The Foundation','The Foundation','The cornerstone of the house, unvarying and unchanging, The Foundation is one of the only constants in the estate on which you can truly rely. This natural cavity was hollowed directly out of the mountain itself, with its stone and earth walls displaying an underlying coarseness that the rest of the mansion conceals.','A pedra angular da casa, invariável e imutável, A Fundação é uma das únicas constantes da propriedade com que você realmente pode contar. Esta cavidade natural foi escavada diretamente da própria montanha, com suas paredes de pedra e terra exibindo uma aspereza latente que o resto da mansão esconde.','Rare','Raro','None (no gem cost)','Nenhum (sem custo em gemas)','Permanent, Blueprint','Permanente (Permanent), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/The%20Foundation.png','https://blueprince.wiki.gg/wiki/The_Foundation',now()),
('Entrance Hall',2,'Entrance Hall','Entrance Hall','Past the steps and beyond the grand doors, admission to Mount Holly is granted by way of a dark and garish lobby, suitably called the Entrance Hall. From here, each guest''s adventure begins; however, the three doors that proceed onward do not always lead to the same adjoining rooms...','Passados os degraus e cruzadas as grandes portas, a entrada em Mount Holly se dá por um saguão escuro e espalhafatoso, apropriadamente chamado de Hall de Entrada. É daqui que começa a aventura de cada hóspede; no entanto, as três portas que seguem adiante nem sempre levam aos mesmos cômodos vizinhos...','n/a','n/d','None (no gem cost)','Nenhum (sem custo em gemas)','Permanent, Blueprint','Permanente (Permanent), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Entrance%20Hall.png','https://blueprince.wiki.gg/wiki/Entrance_Hall',now()),
('Spare Room',3,'Spare Room','Spare Room','An unfurnished, unfinished and otherwise unremarkable empty room. If there had at some point been plans for this spare room, it would seem those designs are now long forgotten.','Um quarto vazio, sem mobília, inacabado e por tudo o mais comum. Se em algum momento houve planos para este quarto reserva, parece que tais projetos há muito foram esquecidos.','Commonplace','Comum','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Spare%20Room.png','https://blueprince.wiki.gg/wiki/Spare_Room',now()),
('Rotunda',4,'Rotunda','Rotunda','A circular chamber with a domed ceiling adorned with an array of mechanical gears. In the center of the room, a stone podium serves as a central pivot point for the chamber''s true purpose: rotation. A fitting function for a room named Rotunda, which means "clockwise room" in Erajan.','Uma câmara circular com teto abobadado adornado por um conjunto de engrenagens mecânicas. No centro do cômodo, um pódio de pedra serve de ponto de pivô central para o verdadeiro propósito da câmara: a rotação. Uma função adequada para um cômodo chamado Rotunda, que significa "cômodo horário" em erajano.','Rare','Raro','3 gems','3 gemas','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Rotunda.png','https://blueprince.wiki.gg/wiki/Rotunda',now()),
('Parlor',5,'Parlor','Parlor','This cozy lounge furnished with couches and armchairs serves as the perfect social setting for receptions and after parties. Consequently this was one of the most popular rooms for entertaining and the late H.S. Sinclair was known to supply a myriad of parlor games to encourage his guests to think and conversate.','Este salão aconchegante, mobiliado com sofás e poltronas, é o cenário social perfeito para recepções e festas. Consequentemente, era um dos cômodos mais populares para o entretenimento, e o falecido H.S. Sinclair era conhecido por oferecer uma infinidade de jogos de salão para incentivar seus convidados a pensar e conversar.','Commonplace','Comum','0 gems','0 gemas','Puzzle, Blueprint','Quebra-cabeça (Puzzle), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Parlor.png','https://blueprince.wiki.gg/wiki/Parlor',now()),
('Billiard Room',6,'Billiard Room','Billiard Room','This smoky backroom, featuring a pool table and fully stocked bar, has served as a retreat on more than one occasion for guests lacking the social wit requried for after-dinner conversation. A rather curious game of darts provided the less competitive players a unique opportunity to ponder over its unusual rules.','Este salão enfumaçado, com mesa de sinuca e bar bem abastecido, já serviu mais de uma vez de refúgio para convidados sem a desenvoltura social exigida na conversa pós-jantar. Um jogo de dardos bastante curioso oferecia aos jogadores menos competitivos uma oportunidade única de refletir sobre suas regras incomuns.','Commonplace','Comum','0 gems','0 gemas','Puzzle, Blueprint','Quebra-cabeça (Puzzle), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Billiard%20Room.png','https://blueprince.wiki.gg/wiki/Billiard_Room',now()),
('Gallery',7,'Gallery','Gallery','A small chamber dedicated to the exhibition of art, ideal for showcasing smaller series and collections. Before his passing, H.S. Sinclair personally selected the artwork that was displayed here each year, purposefully omitting the composition titles to leave the interpretations of each piece for the viewers themselves to realize.','Uma pequena câmara dedicada à exibição de arte, ideal para mostrar séries e coleções menores. Antes de sua morte, H.S. Sinclair selecionava pessoalmente as obras expostas aqui a cada ano, omitindo de propósito os títulos das composições para deixar a interpretação de cada peça a cargo dos próprios espectadores.','Rare','Raro','None (no gem cost)','Nenhum (sem custo em gemas)','Puzzle, Blueprint','Quebra-cabeça (Puzzle), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Gallery.png','https://blueprince.wiki.gg/wiki/Gallery',now()),
('Room 8',8,'Room 8','Room 8','Unsurprisingly, Key 8 unlocked a door leading to a familiar looking room, a cryptic room that had been previewed in the final 8-letter artwork exhibited in the Gallery. It is now time to ruminate over the bins, sins, and pins contained within.','Sem surpresa, a Chave 8 destrancou uma porta que levava a um cômodo de aparência familiar, um cômodo enigmático que já havia sido prenunciado na obra final de 8 letras exposta na Galeria. Chegou a hora de ruminar sobre as latas, os pecados e os pinos ali contidos.','Rare','Raro','0 gems','0 gemas','Puzzle, Blueprint','Quebra-cabeça (Puzzle), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Room%208.png','https://blueprince.wiki.gg/wiki/Room_8',now()),
('Closet',9,'Closet','Closet','A very modest recessed space used for storage. This particular closet is favored by the junior members of the staff, who utilize it to stash away assorted articles and knicknacks[sic] whose proper place in the estate is yet unknown to them.','Um espaço embutido bastante modesto usado para armazenamento. Este armário em particular é preferido pelos membros mais jovens da equipe, que o usam para guardar objetos e bugigangas variados cujo devido lugar na propriedade ainda lhes é desconhecido.','Commonplace','Comum','0 gems','0 gemas','Blueprint, Dead End','Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Closet.png','https://blueprince.wiki.gg/wiki/Closet',now()),
('Walk-In Closet',10,'Walk-In Closet','Walk-In Closet','The stylish and smart clothes in this generously sized closet belong to the former Mistress of the estate, Lady Epsen. Though the small dressing room has not been used in many years, it is nevertheless kept up and preserved in the state you now find it.','As roupas elegantes e refinadas deste closet generosamente amplo pertencem à antiga Senhora da propriedade, Lady Epsen. Embora o pequeno vestiário não seja usado há muitos anos, ele é mesmo assim mantido e preservado no estado em que você o encontra.','Standard','Padrão','1 gem','1 gema','Blueprint, Dead End','Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Walk-In%20Closet.png','https://blueprince.wiki.gg/wiki/Walk-In_Closet',now()),
('Attic',11,'Attic','Attic','High above the mansion in its lofty perch, Mt. Holly''s Attic provides curious explorers with a cache of dusty keepsakes, trinkets, and clues from a long-forgotten past.','Bem no alto da mansão, em seu poleiro elevado, o Sótão de Mt. Holly oferece aos exploradores curiosos um acervo de lembranças empoeiradas, quinquilharias e pistas de um passado há muito esquecido.','Rare','Raro','3 gems','3 gemas','Blueprint, Dead End','Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Attic.png','https://blueprince.wiki.gg/wiki/Attic',now()),
('Storeroom',12,'Storeroom','Storeroom','A dedicated storage space filled from end to end with a surplus of chairs, carpets, paintings and a handful of other things that had at one time been in vogue and on display in other rooms of the house.','Um depósito dedicado, cheio de ponta a ponta com um excedente de cadeiras, tapetes, quadros e uma porção de outras coisas que um dia estiveram em voga e em exibição em outros cômodos da casa.','Commonplace','Comum','0 gems','0 gemas','Blueprint, Dead End','Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 001-012','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20001-012/Storeroom.png','https://blueprince.wiki.gg/wiki/Storeroom',now()),
('Nook',13,'Nook','Nook','A snug corner reading room which serves as a quiet, private place for guests to spend a few hours of their afternoon away from the hustle and bustle of the staff.','Um aconchegante cantinho de leitura que serve de lugar tranquilo e reservado para os hóspedes passarem algumas horas da tarde longe da agitação da equipe.','Commonplace','Comum','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Nook.png','https://blueprince.wiki.gg/wiki/Nook',now()),
('Garage',14,'Garage','Garage','Entering and exiting out through the west facing private drive, the Garage serves as a more practical and informal entrance point into the estate.','Com entrada e saída pela via privativa voltada para o oeste, a Garagem serve como um ponto de acesso mais prático e informal à propriedade.','Unusual','Incomum','1 gem','1 gema','Blueprint, "Dead End"','Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Garage.png','https://blueprince.wiki.gg/wiki/Garage',now()),
('Music Room',15,'Music Room','Music Room','A small recital hall providing an ideal setup for musical performers and accompanists. It is not uncommon for at least a few recitals and performances to be held in this intimate setting each year.','Uma pequena sala de recitais que oferece o ambiente ideal para músicos e acompanhantes. Não é incomum que ao menos alguns recitais e apresentações sejam realizados neste ambiente íntimo a cada ano.','Unusual','Incomum','2 gems','2 gemas','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Music%20Room.png','https://blueprince.wiki.gg/wiki/Music_Room',now()),
('Locker Room',16,'Locker Room','Locker Room','This poolside Locker Room is of course not always poolside, but it is much more convenient for guests when it is; and much less annoying for the servant who must follow the dripping swimmer across the house searching for the locker.','Este Vestiário à beira da piscina obviamente nem sempre fica à beira da piscina, mas é muito mais conveniente para os hóspedes quando fica; e muito menos irritante para o criado que teria de seguir o nadador pingando pela casa em busca do armário.','Rare','Raro','1 gem','1 gema','Spread, Blueprint, Addition','Propagação (Spread), Blueprint (planta azul), Adição (Addition)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Locker%20Room.png','https://blueprince.wiki.gg/wiki/Locker_Room',now()),
('Den',17,'Den','Den','A more traditional family room, warm and inviting. So comfortable, one might assume that the countless clocks surrounding the sofas are placed in a futile attempt to avoid inevitably wasting the entire day here.','Uma sala de estar mais tradicional, quente e acolhedora. Tão confortável que se poderia supor que os incontáveis relógios ao redor dos sofás foram colocados numa tentativa fútil de evitar desperdiçar o dia inteiro aqui.','Commonplace','Comum','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Den.png','https://blueprince.wiki.gg/wiki/Den',now()),
('Wine Cellar',18,'Wine Cellar','Wine Cellar','A short staircase leads down to this below ground cellar revealing an impressive collection of bottles from every respectable vintage of the last 200 years. To the seasoned wine aficionado, the labels displayed here would indicate a preference for prioritizing extravagance and rarity over quality.','Uma curta escadaria desce até esta adega subterrânea, revelando uma impressionante coleção de garrafas de todas as safras respeitáveis dos últimos 200 anos. Para o apreciador experiente de vinhos, os rótulos exibidos aqui indicariam uma preferência por priorizar a extravagância e a raridade em vez da qualidade.','Unusual','Incomum','0 gems','0 gemas','Blueprint, Dead End','Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Wine%20Cellar.png','https://blueprince.wiki.gg/wiki/Wine_Cellar',now()),
('Trophy Room',19,'Trophy Room','Trophy Room','The polished brass of the treasured laurels filling the trophy cases of this room reveal the pride their owner must feel having earned them. Achievement is its own reward but a gold cup is also nice.','O latão polido dos preciosos louros que enchem as estantes de troféus deste cômodo revela o orgulho que seu dono deve sentir por tê-los conquistado. A conquista é sua própria recompensa, mas uma taça de ouro também é bom.','Rare','Raro','5 gems','5 gemas','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Trophy%20Room.png','https://blueprince.wiki.gg/wiki/Trophy_Room',now()),
('Ballroom',20,'Ballroom','Ballroom','An opulent hall with a polished mirror floor. In the old days, numerous balls and dances were held in this splendid room. However, as he aged, the Baron began to prefer private parties in the Parlor over the grand formal receptions of his youth.','Um salão opulento com piso de espelho polido. Nos velhos tempos, inúmeros bailes e danças eram realizados neste esplêndido salão. Contudo, à medida que envelhecia, o Barão passou a preferir festas privadas no Salão em vez das grandiosas recepções formais de sua juventude.','Unusual','Incomum','2 gems','2 gemas','Entry, Blueprint','Entrada (Entry), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Ballroom.png','https://blueprince.wiki.gg/wiki/Ballroom',now()),
('Pantry',21,'Pantry','Pantry','A well stocked pantry is always the true test of a large estate, and keeping Mt. Holly''s wide gamut of ingredients and supplies stocked has always been one of the primary priorities of the house staff.','Uma despensa bem abastecida é sempre o verdadeiro teste de uma grande propriedade, e manter em estoque a ampla gama de ingredientes e suprimentos de Mt. Holly sempre foi uma das principais prioridades da equipe da casa.','Commonplace','Comum','None (no gem cost)','Nenhum (sem custo em gemas)','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Pantry.png','https://blueprince.wiki.gg/wiki/Pantry',now()),
('Rumpus Room',22,'Rumpus Room','Rumpus Room','A uniquely modern fashioned gaming room, the Rumpus Room has provided many guests of the estate with countless hours of recreations. The room is outfitted with a record player, two television sets, a collection of board games and a mysterious antique fortune telling automaton named "Alzara".','Uma sala de jogos de estilo singularmente moderno, a Sala de Recreação proporcionou a muitos hóspedes da propriedade incontáveis horas de diversão. O cômodo é equipado com uma vitrola, dois aparelhos de televisão, uma coleção de jogos de tabuleiro e um misterioso autômato antigo de adivinhação chamado "Alzara".','Standard','Padrão','1 gem','1 gema','Blueprint','Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Rumpus%20Room.png','https://blueprince.wiki.gg/wiki/Rumpus_Room',now()),
('Vault',23,'Vault','Vault','A secure onsite depository fitted with steel walls and numbered lockers. This fortified strongroom holds a good portion of the Sinclair fortune despite the fact that several inventories have led accountants to assume the true legacy is hidden elsewhere.','Um depósito seguro no local, revestido de paredes de aço e armários numerados. Este cofre-forte guarda boa parte da fortuna dos Sinclair, apesar de vários inventários terem levado os contadores a supor que o verdadeiro legado esteja escondido em outro lugar.','Rare','Raro','3 gems','3 gemas','Blueprint, Dead End','Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Vault.png','https://blueprince.wiki.gg/wiki/Vault',now()),
('Office',24,'Office','Office','The late Sinclair''s personal home office, a room he used exclusively for business affairs and the running of the estate, a task he took increasingly more satisfaction in overseeing in his later years.','O escritório particular do falecido Sinclair, um cômodo que ele usava exclusivamente para assuntos de negócios e para a administração da propriedade, tarefa da qual passou a extrair cada vez mais satisfação em seus últimos anos.','Standard','Padrão','2 gems','2 gemas','Spread, Blueprint','Propagação (Spread), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 013-024','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20013-024/Office.png','https://blueprince.wiki.gg/wiki/Office',now()),
('Drawing Room',25,'Drawing Room','Drawing Room','A social sitting room adorned wall to wall with artwork and drawings. An unfinished sketch of your uncle sits on an easel in the middle of the room, providing a vivid image of what were presumably his final days (depending on when the project was abandoned).','Uma sala de estar social adornada de parede a parede com obras de arte e desenhos. Um esboço inacabado de seu tio está sobre um cavalete no meio do cômodo, oferecendo uma imagem vívida do que presumivelmente foram seus últimos dias (dependendo de quando o projeto foi abandonado).','Commonplace','Comum','1 gem','1 gema','Drafting, Blueprint','Sorteio (Drafting), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Drawing%20Room.png','https://blueprince.wiki.gg/wiki/Drawing_Room',now()),
('Study',26,'Study','Study','After the passing of Baroness Auravei, her private study was claimed by her eldest son, Herbert Sinclair. For years, he immersed himself in the countless notebooks she left behind, drawing inspiration from her discarded ideas. From mechanical puzzles to architectural blueprints, each endeavor he pursued in this room was realized in the shade of her creative legacy.','Após a morte da Baronesa Auravei, seu escritório particular foi tomado por seu filho mais velho, Herbert Sinclair. Durante anos, ele mergulhou nos incontáveis cadernos que ela deixou, buscando inspiração em suas ideias descartadas. De quebra-cabeças mecânicos a plantas arquitetônicas, cada empreitada que ele buscou neste cômodo foi realizada à sombra do legado criativo dela.','Unusual','Incomum','0 gems','0 gemas','Drafting, Blueprint, Dead End','Sorteio (Drafting), Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Study.png','https://blueprince.wiki.gg/wiki/Study',now()),
('Library',27,'Library','Library','Two stories of wall-to-wall books surround the reader in this room, exhibiting either a bountiful spring of knowledge or typical interior design sensibilities of the wealthy. A few books have been withdrawn from the shelves and placed on rostrum stands in various corners of the library.','Dois andares de livros de parede a parede cercam o leitor neste cômodo, exibindo ou uma fonte abundante de conhecimento ou o típico bom gosto de decoração dos ricos. Alguns livros foram retirados das prateleiras e colocados em estantes de leitura em vários cantos da biblioteca.','Unusual','Incomum','0 gems','0 gemas','Drafting, Blueprint','Sorteio (Drafting), Blueprint (planta azul)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Library.png','https://blueprince.wiki.gg/wiki/Library',now()),
('Chamber of Mirrors',28,'Chamber of Mirrors','Chamber of Mirrors','Reflections of reflections, this confusing room can sometimes prove disorienting to the wayward guest. However, upon closer inspection, they quickly realize that viewing this room from more than one perspective is key to unraveling its secrets.','Reflexos de reflexos, este cômodo confuso pode às vezes desorientar o hóspede desavisado. No entanto, olhando mais de perto, ele logo percebe que ver este cômodo de mais de uma perspectiva é a chave para desvendar seus segredos.','Rare','Raro','0 gems','0 gemas','Drafting, Blueprint, "Dead End"','Sorteio (Drafting), Blueprint (planta azul), Beco sem saída (Dead End)',ARRAY['Blueprint']::text[],'Rooms 025-036','https://gppfzdlqauygzvpodbdh.supabase.co/storage/v1/object/public/salas/Rooms%20025-036/Chamber%20of%20Mirrors.png','https://blueprince.wiki.gg/wiki/Chamber_of_Mirrors',now()) on conflict (nome) do update set num=excluded.num,nome_en=excluded.nome_en,nome_pt=excluded.nome_pt,descricao_en=excluded.descricao_en,descricao_pt=excluded.descricao_pt,raridade_en=excluded.raridade_en,raridade_pt=excluded.raridade_pt,custo_en=excluded.custo_en,custo_pt=excluded.custo_pt,tipo_en=excluded.tipo_en,tipo_pt=excluded.tipo_pt,categorias=excluded.categorias,diretorio=excluded.diretorio,imagem=excluded.imagem,fonte=excluded.fonte,atualizado_em=excluded.atualizado_em;
